const { env } = process;
if (!env.INPUT_PATH) throw new Error('Missing INPUT_PATH');
if (!env.OUTPUT_PATH) throw new Error('Missing OUTPUT_PATH');
globalThis.inputPath = env.INPUT_PATH;
globalThis.outputPath = env.OUTPUT_PATH;

const fs = await import('node:fs');
const { encode } = await import('algorand-msgpack');
const raw = fs.readFileSync(globalThis.inputPath, 'utf8');
const data = JSON.parse(raw);
const encoded = encode(data);
fs.writeFileSync(globalThis.outputPath, Buffer.from(encoded));
